def f():
    raise ValueError("inner")

try:
    f()
except ValueError as e:
    raise TypeError("outer") from e

执行下面代码会发生什么？

try:
    raise Exception("a")
except Exception:
    raise Exception("b")

执行下面代码，输出结果是什么？

def check(x):
    if x < 0:
        raise ValueError("negative")
    return x

print(check(-1))

